<?php
namespace Avanik;
defined('ABSPATH') || exit;
final class ProductBooking {
 public static function register(): void { add_shortcode('avanik_product_checkout',[self::class,'render']); add_action('admin_post_avanik_product_checkout',[self::class,'checkout']); }
 public static function render(): string { if(!is_user_logged_in())return '<p>برای رزرو ابتدا وارد حساب کاربری شوید.</p>'; $id=absint($_GET['product_id']??0); global $wpdb; $p=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.ProductRepository::table_name().' WHERE id=%d AND status=%s',$id,Product::PUBLISHED),ARRAY_A); if(!$p)return '<p>محصول قابل رزرو نیست.</p>'; $max=max(1,(int)$p['capacity']); $fields=PassengerRequirements::for_product($p); $labels=PassengerRequirements::labels(); ob_start(); ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" dir="rtl"><input type="hidden" name="action" value="avanik_product_checkout"><input type="hidden" name="product_id" value="<?php echo esc_attr($id); ?>"><?php wp_nonce_field('avanik_product_checkout'); ?><p><label>تعداد مسافر<br><input type="number" name="quantity" min="1" max="<?php echo esc_attr($max); ?>" value="1" required></label></p><div id="avanik-passengers"><?php echo self::passenger_template(1,$fields,$labels); ?></div><p><button type="button" id="avanik-add-passenger">افزودن مسافر</button></p><h3>روش پرداخت</h3><label><input type="radio" name="payment_gateway" value="manual" checked> کارت به کارت</label> <label><input type="radio" name="payment_gateway" value="zarinpal"> زرین‌پال</label><p><button type="submit">ثبت رزرو و ادامه پرداخت</button></p></form><script>(function(){const q=document.querySelector('[name=quantity]'),box=document.getElementById('avanik-passengers'),add=document.getElementById('avanik-add-passenger');const tpl=box.innerHTML;function sync(){let n=Math.max(1,Math.min(parseInt(q.value||1,10),parseInt(q.max||99,10)));box.innerHTML='';for(let i=0;i<n;i++){let html=tpl.replaceAll('__N__',String(i+1));box.insertAdjacentHTML('beforeend',html);} }q.addEventListener('change',sync);add.addEventListener('click',()=>{q.value=Math.min(parseInt(q.max||99,10),parseInt(q.value||1,10)+1);sync();});sync();})();</script><?php return (string)ob_get_clean(); }
 private static function passenger_template(int $n,array $fields,array $labels): string { ob_start(); ?><fieldset class="avanik-passenger"><legend>مسافر <?php echo esc_html($n); ?></legend><?php foreach($fields as $field): $type=in_array($field,['date_of_birth','passport_expiry'],true)?'date':($field==='email'?'email':'text'); ?><p><label><?php echo esc_html($labels[$field]); ?><br><input type="<?php echo esc_attr($type); ?>" name="passengers[__N__][<?php echo esc_attr($field); ?>]" <?php echo in_array($field,['first_name','last_name','passport_no','passport_expiry'],true)?'required':''; ?>></label></p><?php endforeach; ?></fieldset><?php return (string)ob_get_clean(); }
 public static function checkout(): void { if(!is_user_logged_in()||!check_admin_referer('avanik_product_checkout'))wp_die('Unauthorized'); global $wpdb; $id=absint($_POST['product_id']??0); $p=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.ProductRepository::table_name().' WHERE id=%d AND status=%s',$id,Product::PUBLISHED),ARRAY_A); if(!$p)wp_die('Product unavailable'); $qty=max(1,absint($_POST['quantity']??1)); if((int)$p['capacity']>0&&$qty>(int)$p['capacity'])wp_die('ظرفیت کافی نیست.'); $fields=PassengerRequirements::for_product($p); $passengers=(array)($_POST['passengers']??[]); if(count($passengers)!==$qty)wp_die('تعداد اطلاعات مسافران با تعداد انتخابی برابر نیست.'); foreach($passengers as $index=>$passenger){$errors=PassengerRequirements::validate((array)$passenger,$fields); if($errors)wp_die('اطلاعات مسافر '.esc_html((string)$index).' کامل نیست.');} $meta=json_decode((string)$p['metadata'],true)?:[]; $first=(array)$passengers[0]; $booking=BookingRepository::create(['customer_id'=>get_current_user_id(),'product_id'=>$id,'booking_type'=>$p['type'],'destination'=>$meta['destination']??'','travel_date'=>$meta['start_date']??'','quantity'=>$qty,'passenger_name'=>trim(($first['first_name']??'').' '.($first['last_name']??'')),'passenger_phone'=>$first['phone']??'','passenger_email'=>$first['email']??'','total_amount'=>(float)$p['price']*$qty]); if(!$booking)wp_die('رزرو ایجاد نشد.'); $inserted=[]; foreach($passengers as $passenger){$pid=BookingPassengers::add($booking,(array)$passenger); if(!$pid){foreach($inserted as $x){$wpdb->delete(BookingPassengers::table_name(),['id'=>$x],['%d']);} BookingRepository::delete_by_id($booking); wp_die('ذخیره اطلاعات مسافران ناموفق بود.');}$inserted[]=$pid;} $gateway=sanitize_key($_POST['payment_gateway']??'manual'); $payment=PaymentService::initialize(['booking_id'=>$booking,'customer_id'=>get_current_user_id(),'amount'=>(float)$p['price']*$qty,'currency'=>$p['currency'],'gateway'=>$gateway]); if(is_wp_error($payment)){foreach($inserted as $x){$wpdb->delete(BookingPassengers::table_name(),['id'=>$x],['%d']);} BookingRepository::delete_by_id($booking); wp_die($payment->get_error_message());} wp_safe_redirect(home_url('/payment/?transaction_id='.rawurlencode($payment['transaction_id']))); exit; }
}